'use strict';
const $=(s,root=document)=>root.querySelector(s);
// Resolve assets inside this deployment: '/' locally or '/simworld/' on Pages.
// Keeping the base tied to the HTML document also supports custom domains.
const SITE_BASE=new URL('.',document.baseURI);
let project,selectedPhase=0,group='all',category='all';
const toast=(text)=>{const el=$('#toast');el.textContent=text;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),2800)};
async function copy(text){try{await navigator.clipboard.writeText(text);toast('Copied to clipboard')}catch{toast('Clipboard unavailable. Select the text to copy.')}}
const escape=(s)=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const phaseGroup=(id)=>id<=6?'physical':id<=9?'living':id<=13?'social':'integration';
function localURL(url){
  if(typeof url!=='string'||url.startsWith('//')||url.includes('\\')||/^[a-z][a-z\d+.-]*:/i.test(url))return '#';
  const resolved=new URL(url.replace(/^\/+/,''),SITE_BASE);
  // Dataset URLs may only address this site's own publication directory.
  return resolved.origin===SITE_BASE.origin&&resolved.pathname.startsWith(SITE_BASE.pathname)?resolved.href:'#';
}
const size=(n)=>n>=1048576?`${(n/1048576).toFixed(1)} MB`:`${Math.ceil(n/1024)} KB`;
function openDocByURL(url,title){const doc=project.documents.find(d=>d.url===url||d.id===url);openDocument(doc||{url,title:title||'Project document'})}
function renderPhases(){const phases=project.phases.filter(p=>group==='all'||phaseGroup(Number(p.id))===group);if(!phases.some(p=>Number(p.id)===selectedPhase))selectedPhase=Number(phases[0].id);$('#phase-list').innerHTML=phases.map(p=>`<button class="phase-button ${Number(p.id)===selectedPhase?'active':''}" data-phase="${p.id}" aria-pressed="${Number(p.id)===selectedPhase}"><span>${String(p.id).padStart(2,'0')}</span><span>${escape(p.title)}</span><span aria-hidden="true">↗</span></button>`).join('');$('#phase-list').querySelectorAll('button').forEach(b=>b.addEventListener('click',()=>{selectedPhase=Number(b.dataset.phase);renderPhases()}));const p=project.phases.find(p=>Number(p.id)===selectedPhase);const state=Number(p.id)===0?'REDUCED PROTOTYPE IMPLEMENTED':p.documentAvailable?'DETAILED RESEARCH PROPOSAL':'ROADMAP OUTLINE';const docURL=typeof p.document==='object'?p.document?.url:p.document;$('#phase-detail').innerHTML=`<span class="phase-number">${String(p.id).padStart(2,'0')}</span><p class="eyebrow">${state}</p><h3>${escape(p.title)}</h3><p>${escape(p.summary||p.description)}</p><div class="phase-facts"><div><h4>PROPOSED MECHANISMS</h4><ul>${(p.mechanisms||[]).map(x=>`<li>${escape(x)}</li>`).join('')}</ul></div><div><h4>WHAT NEEDS TO BE SHOWN</h4><ul>${(p.criteria||[]).map(x=>`<li>${escape(x)}</li>`).join('')}</ul></div></div><button class="inline-link phase-read" style="background:none;border:0;border-bottom:1px solid #91a396;padding:0 0 4px">${p.documentAvailable?'Read the phase plan':'Read the full roadmap'} ↗</button>`;$('.phase-read').addEventListener('click',()=>openDocByURL(p.documentAvailable?docURL:'/docs/ROADMAP.md',p.title))}
function renderDocuments(){const query=$('#document-search').value.trim().toLowerCase();const docs=project.documents.filter(d=>{const isSpec=/spec|constant|decision|interface|seam|surprise/i.test(d.category+' '+d.url);return(category==='all'||(category==='specification'?isSpec:!isSpec))&&(d.title+' '+d.id+' '+d.category).toLowerCase().includes(query)});$('#document-count').textContent=`${docs.length} DOCUMENT${docs.length===1?'':'S'}`;$('#document-list').innerHTML=docs.length?docs.map((d,i)=>`<div class="document-row"><button class="document-open" data-index="${i}"><span class="document-icon">MD</span><span class="document-name">${escape(d.title)}<small>${escape(d.category||'DOCUMENTATION')}</small></span></button><a href="${localURL(d.url)}" download aria-label="Download ${escape(d.title)}">↓</a></div>`).join(''):'<p class="empty-state">No matching documents. Try another search.</p>';$('#document-list').querySelectorAll('.document-open').forEach(b=>b.addEventListener('click',()=>openDocument(docs[Number(b.dataset.index)])))}
function inline(text){return escape(text).replace(/`([^`]+)`/g,'<code>$1</code>').replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>').replace(/\*([^*]+)\*/g,'<em>$1</em>')}
function markdown(source){const lines=source.replace(/\r\n/g,'\n').split('\n');let out=[],para=[],list=false,code=false,buf=[];const flush=()=>{if(para.length){out.push(`<p>${inline(para.join(' '))}</p>`);para=[]}if(list){out.push('</ul>');list=false}};for(let i=0;i<lines.length;i++){const line=lines[i];if(line.trim().startsWith('```')){flush();if(code){out.push(`<pre><code>${escape(buf.join('\n'))}</code></pre>`);buf=[]}code=!code;continue}if(code){buf.push(line);continue}if(!line.trim()){flush();continue}const heading=line.match(/^(#{1,6})\s+(.+)/);if(heading){flush();const n=Math.min(heading[1].length,4);out.push(`<h${n}>${inline(heading[2])}</h${n}>`);continue}if(/^\s*\|/.test(line)&&i+1<lines.length&&/^\s*\|[\s:|\-]+\|?\s*$/.test(lines[i+1])){flush();const cells=l=>l.trim().replace(/^\||\|$/g,'').split('|').map(x=>x.trim());out.push('<div class="table-scroll"><table><thead><tr>'+cells(line).map(c=>`<th>${inline(c)}</th>`).join('')+'</tr></thead><tbody>');i++;while(i+1<lines.length&&/^\s*\|/.test(lines[i+1])){i++;out.push('<tr>'+cells(lines[i]).map(c=>`<td>${inline(c)}</td>`).join('')+'</tr>')}out.push('</tbody></table></div>');continue}const li=line.match(/^\s*(?:[-*]|\d+\.)\s+(.+)/);if(li){if(para.length){out.push(`<p>${inline(para.join(' '))}</p>`);para=[]}if(!list){out.push('<ul>');list=true}out.push(`<li>${inline(li[1]).replace(/^\[ \]/,'☐').replace(/^\[x\]/i,'☑')}</li>`);continue}if(/^\s*---+\s*$/.test(line)){flush();out.push('<hr>');continue}if(/^>\s?/.test(line)){flush();out.push(`<blockquote>${inline(line.replace(/^>\s?/,''))}</blockquote>`);continue}para.push(line)}flush();if(code)out.push(`<pre><code>${escape(buf.join('\n'))}</code></pre>`);return out.join('')}
let docRequest=0;
async function openDocument(doc){const token=++docRequest;const dialog=$('#document-dialog');$('#document-title').textContent=doc.title;$('#document-download').href=localURL(doc.url);$('#document-content').textContent='Loading document…';if(!dialog.open)dialog.showModal();dialog.scrollTop=0;document.body.style.overflow='hidden';try{const r=await fetch(localURL(doc.url));if(!r.ok)throw Error('Unable to load this document.');const source=await r.text();if(token!==docRequest)return;$('#document-content').innerHTML=markdown(source)}catch(error){if(token===docRequest)$('#document-content').textContent=error.message}}
function renderDownloads(){const entries=project.downloads;$('#download-list').innerHTML=entries.map((d,i)=>`<article class="download-card"><div class="download-format"><span>${escape(d.format||d.filename.split('.').pop().toUpperCase())}</span><span>${size(d.bytes)}</span></div><h3>${escape(d.title)}</h3><p>${escape(d.description)}</p><a class="download-action" href="${localURL(d.url)}" download="${escape(d.filename)}">Download ${escape(d.format||'file')} <span>↓</span></a><button class="checksum" data-index="${i}" aria-label="Copy SHA-256 checksum for ${escape(d.title)}">SHA-256 ${escape(d.sha256?.slice(0,16))}… · Copy</button></article>`).join('');$('#download-list').querySelectorAll('.checksum').forEach(b=>b.addEventListener('click',()=>copy(entries[Number(b.dataset.index)].sha256)));const pdf=entries.find(x=>x.format?.toLowerCase()==='pdf'||x.url.endsWith('.pdf'));if(pdf)document.querySelectorAll('.paper-link').forEach(a=>{a.href=localURL(pdf.url);a.target='_blank';a.rel='noopener'})}
function renderReferences(){const refs=project.references||[];$('#reference-list').innerHTML=refs.map((r,i)=>{const url=r.url||`https://doi.org/${r.doi}`;return `<a class="reference-link" href="${/^https:\/\//.test(url)?escape(url):'#'}" target="_blank" rel="noopener noreferrer"><span>${String(i+1).padStart(2,'0')}</span><span><strong>${escape(r.title)}</strong><small>${escape(Array.isArray(r.authors)?r.authors.join(', '):r.authors||'')} · ${escape(r.year||'')}</small></span><span>↗</span></a>`}).join('')}
$('.menu-toggle').addEventListener('click',()=>{const b=$('.menu-toggle');const open=b.getAttribute('aria-expanded')!=='true';b.setAttribute('aria-expanded',open);$('#navigation').classList.toggle('open',open)});$('#navigation').querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{$('#navigation').classList.remove('open');$('.menu-toggle').setAttribute('aria-expanded','false')}));document.querySelectorAll('.group-button').forEach(b=>b.addEventListener('click',()=>{group=b.dataset.group;document.querySelectorAll('.group-button').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',x===b)});if(project)renderPhases()}));document.querySelectorAll('.filter-button').forEach(b=>b.addEventListener('click',()=>{category=b.dataset.filter;document.querySelectorAll('.filter-button').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',x===b)});if(project)renderDocuments()}));$('#document-search').addEventListener('input',()=>project&&renderDocuments());$('#copy-command').addEventListener('click',()=>copy($('#reproduction-command').textContent.trim()));$('#close-document').addEventListener('click',()=>$('#document-dialog').close());$('#document-dialog').addEventListener('close',()=>{document.body.style.overflow='';docRequest++});$('#document-dialog').addEventListener('click',e=>{if(e.target===$('#document-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}});
fetch(localURL('/data/project.json')).then(r=>{if(!r.ok)throw Error('Project data could not be loaded.');return r.json()}).then(data=>{project=data;$('#roadmap-coverage').textContent=data.provenance.currentDocumentation+' The white paper preserves its earlier 29 October research snapshot.';renderPhases();renderDocuments();renderDownloads();renderReferences()}).catch(error=>{$('#phase-list').textContent=error.message;$('#document-list').textContent='The project data is unavailable. Please refresh the page.';$('#download-list').innerHTML=`<p>Download the <a class="inline-link" href="${localURL('/downloads/SimWorld_Research_White_Paper.pdf')}">white paper directly</a>.</p>`;console.error(error)});
